import type { ReactNode } from "react";

import { IconPlay } from "@rhs-ui/icons";
import { Button } from "@rhs-ui/primitives/button";
import { VideoDialog, type VideoCaption, type VideoSource } from "@rhs-ui/primitives/video-dialog";

function Example({ caption, children }: { caption: string; children: ReactNode }): React.JSX.Element {
  return (
    <div className="grid min-w-0 grid-cols-[minmax(0,1fr)] content-start gap-3">
      <p className="text-xs text-muted-foreground">{caption}</p>
      {children}
    </div>
  );
}

export default function Demo(): React.JSX.Element {
  return (
    <div className="grid w-full max-w-xl gap-10">
      <Example caption="The default trigger is a poster with a play button. The player starts when the dialog opens, stops when it closes, and focus goes back here">
        <VideoDialog title="Halcyon product tour" poster={POSTER} sources={SOURCES} captions={CAPTIONS} />
      </Example>

      <Example caption="Any element can be the trigger, and the video can wait for the first press of play">
        <div className="flex flex-wrap items-center gap-x-4 gap-y-3 rounded-xl border border-border bg-card p-4 shadow-xs">
          <VideoDialog
            title="Halcyon product tour"
            poster={POSTER}
            sources={SOURCES}
            captions={CAPTIONS}
            autoPlay={false}
            trigger={
              <Button type="button">
                <IconPlay />
                Watch the tour
              </Button>
            }
          />
          <p className="min-w-0 flex-1 basis-48 text-sm text-muted-foreground">Seeing it is quicker than reading about it. It plays here, without leaving the page.</p>
        </div>
      </Example>
    </div>
  );
}

/** A picture drawn in SVG, as an address a picture or a video poster can use. */
const svg = (markup: string) => `data:image/svg+xml;utf8,${encodeURIComponent(markup)}`;

const POSTER = svg(
  '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 480 270"><rect width="480" height="270" fill="#0e0e0e"/><path d="M30 0V270M60 0V270M90 0V270M120 0V270M150 0V270M180 0V270M210 0V270M240 0V270M270 0V270M300 0V270M330 0V270M360 0V270M390 0V270M420 0V270M450 0V270M0 30H480M0 60H480M0 90H480M0 120H480M0 150H480M0 180H480M0 210H480M0 240H480" fill="none" stroke="#f2f2f2" stroke-opacity=".07"/><g fill="none" stroke="#f2f2f2" stroke-width="1.5"><circle cx="240" cy="135" r="30" opacity=".95"/><circle cx="240" cy="135" r="58" opacity=".4"/><circle cx="240" cy="135" r="88" opacity=".16"/></g><circle cx="240" cy="135" r="5" fill="#f2f2f2"/></svg>',
);

const CAPTIONS: readonly VideoCaption[] = [
  {
    src: `data:text/vtt;charset=utf-8,${encodeURIComponent("WEBVTT\n\n00:00.000 --> 00:01.400\nMeet Halcyon.\n\n00:01.500 --> 00:02.900\nYour whole team, in one calm place.\n")}`,
    label: "English",
    language: "en",
    default: true,
  },
];

/** A three second clip of 960 by 540 pixels, as two files: the browser plays the first kind it can. */
const SOURCES: readonly VideoSource[] = [
  { src: "data:video/mp4;base64,", type: 'video/mp4; codecs="avc1.42E01E"' },
  { src: "data:video/webm;base64,", type: 'video/webm; codecs="vp9"' },
];
